+    public JsonParser filter(JsonParser parser) {
+        JsonParser filtered = parser;
+        if (excludes != null) {
+            for (FilterPath e : excludes) {
+                if (e.hasDoubleWildcard()) {
+                    // Fixed in Jackson 2.13 - https://github.com/FasterXML/jackson-core/issues/700
