-
-        executeAsyncWithOrigin(
-            client.threadPool().getThreadContext(),
-            ML_ORIGIN,
-            createIndexRequest,
-            ActionListener.<CreateIndexResponse>wrap(r -> listener.onResponse(r.isAcknowledged()), listener::onFailure),
-            client.admin().indices()::create
-        );
