-    public static class JobsAndDatafeeds {
-        List<Job> jobs;
-        List<DatafeedConfig> datafeedConfigs;
-
-        private JobsAndDatafeeds() {
-            jobs = new ArrayList<>();
-            datafeedConfigs = new ArrayList<>();
